[CmdletBinding()]
param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'; $root=(Resolve-Path $ProjectRoot).Path; $fixture=Join-Path ([IO.Path]::GetTempPath()) ("m7-negative-"+[guid]::NewGuid().ToString('N'))
try { New-Item -ItemType Directory -Path (Join-Path $fixture 'M7') -Force|Out-Null; New-Item -ItemType Directory -Path (Join-Path $fixture 'benchmarks') -Force|Out-Null; Copy-Item (Join-Path $root 'M7/*.lean') (Join-Path $fixture 'M7'); Copy-Item (Join-Path $root 'benchmarks/m7_benchmark_05.json') (Join-Path $fixture 'benchmarks'); $p=Join-Path $fixture 'benchmarks/m7_benchmark_05.json'; $m=Get-Content -Raw $p|ConvertFrom-Json; $m.cases[0].lean_declaration='m7_corrupted'; $m|ConvertTo-Json -Depth 8|Set-Content $p; try { foreach($c in $m.cases){$s=Get-Content -Raw (Join-Path $fixture 'M7/Benchmark.lean');if(-not $s.Contains("theorem $($c.lean_declaration)")){throw 'M7 manifest mutation rejected'}}; throw 'M7 negative mutation was accepted' } catch { if($_.Exception.Message -eq 'M7 negative mutation was accepted'){throw} }; Write-Host 'M7 negative gate: PASS' } finally {if(Test-Path $fixture){Remove-Item $fixture -Recurse -Force}}
